      "title": "La guardia",
      "partId": "parte-viii",
      "blocks": [
        {
          "type": "paragraph",
          "text": "Se dobbiamo scegliere una funzione capace di spiegare la persistenza del Cane Corso, la guardia occupa un posto centrale nella lettura del Dott. Flavio Bruno. Ma guardia non significa reazione indiscriminata."
        },
        {
          "type": "paragraph",
          "text": "La guardia non è abbaiare a tutto."
        },
        {
          "type": "paragraph",
          "text": "Non è l’aggressione indiscriminata. Non è costruire un animale ingestibile e chiamarlo “forte”."
        },
        {
          "type": "paragraph",
          "text": "La guardia è una funzione complessa. Richiede territorialità, attenzione, sicurezza, capacità di distinguere la normalità dall’anomalia e legame con la persona o il luogo da proteggere."
        },
        {
          "type": "paragraph",
          "text": "Dott. Flavio Bruno descrive il Cane Corso come cane di guardia per eccellenza in molti contesti del Sud. Questa affermazione storica, quando viene resa quantitativa o geografica, dovrà essere verificata. Ma la sua idea funzionale è chiarissima: il Cane Corso deve essere utile alla protezione reale."
        },
        {
          "type": "paragraph",
          "text": "Per me la guardia è forse la funzione più facilmente osservabile oggi senza ricostruire artificialmente lavori scomparsi. Non serve creare pericoli. Basta vedere come il cane gestisce il proprio ambiente."
        },
        {
          "type": "paragraph",
          "text": "Un buon Cane non vive in uno stato permanente di conflitto. Sa stare tranquillo perché sa anche diventare serio quando la situazione cambia."
        },
        {
          "type": "paragraph",
          "text": "La forza più importante non è partire. È sapere perché partire."
        },
        {
          "type": "paragraph",
          "text": "La guardia è probabilmente la funzione che più spesso viene falsificata dalla teatralità. Un cane che abbaia a ogni rumore può sembrare vigile. Un cane che si lancia continuamente verso la recinzione può sembrare coraggioso. Ma se non sa distinguere, non sta lavorando meglio: sta reagendo di più."
        },
        {
          "type": "paragraph",
          "text": "Nel sistema rurale descritto dal Dott. Flavio Bruno, il Cane Corso doveva convivere con una quantità enorme di stimoli normali: persone conosciute, animali, carri, rumori, visite, lavoro quotidiano. Se avesse interpretato tutto come minaccia, sarebbe stato inutilizzabile. La guardia efficace nasce quindi anche dall’abitudine alla normalità."
        },
        {
          "type": "paragraph",
          "text": "Per questo oggi possiamo osservare la funzione di guardia senza creare provocazioni pericolose. Possiamo vedere se il cane è sicuro nel proprio ambiente, se nota il cambiamento, se cerca il riferimento del proprio uomo, se recupera rapidamente dopo uno stimolo, se non vive in paura permanente."
        },
        {
          "type": "paragraph",
          "text": "La vera potenza della guardia sta nella possibilità dell’azione, non nella sua esibizione continua. Il Cane tranquillo non è necessariamente meno guardiano. Talvolta è proprio la sicurezza che gli permette di risparmiare la reazione per quando serve."
        },
        {
          "type": "paragraph",
          "text": "Dott. Flavio Bruno direbbe che il cane deve avere coscienza. Io aggiungerei: deve avere anche una ragione per fidarsi del proprio uomo."
        },
        {
          "type": "heading",
          "text": "Guardia non significa sospetto permanente"
        },
        {
          "type": "paragraph",
          "text": "Un buon guardiano non vive in guerra con il mondo. Osserva. Riconosce il normale. Nota ciò che cambia."
        },
        {
          "type": "paragraph",
          "text": "Dott. Flavio Bruno mi ha descritto più volte il Cane Corso come un cane vicino all'uomo, capace di custodire proprietà e persone senza trasformare ogni incontro in conflitto. Nella masseria questa qualità era indispensabile: entravano familiari, lavoratori, clienti, animali. Un cane incontrollabile avrebbe creato più problemi di quanti ne risolvesse."
        },
        {
          "type": "paragraph",
          "text": "Anche il tradizionale abbinamento con il Volpino raccontato dal Dott. Flavio Bruno è interessante: il piccolo cane vigile segnala, il Cane Corso interviene se necessario. È un sistema di funzioni complementari, non una gara a chi è più aggressivo."
        },
        {
          "type": "paragraph",
          "text": "La guardia moderna dovrebbe ricordare questa lezione. Proteggere non significa impedire al cane di vivere socialmente. Significa selezionare stabilità, relazione con il proprietario e capacità di discriminazione."
        },
        {
          "type": "paragraph",
          "text": "Se la guardia aiuta a spiegare la continuità funzionale, il colore mostra l’opposto: una caratteristica immediatamente visibile che può diventare troppo importante quando perdiamo di vista l’insieme."
        }
      ],
      "editorialNotes": []
